.ds-card-service { background: #FFFFFF; border: 1px solid #E2E5EB; border-radius: 8px; padding: 16px; box-shadow: 0 2px 4px rgba(27, 35, 54, 0.04), 0 1px 2px rgba(27, 35, 54, 0.02); font-family: 'Manrope', sans-serif; }
.ds-card-service h3 { margin: 0 0 8px; font-family: 'Playfair Display', serif; font-size: 18px; color: #1B2336; font-weight: 600; }
.ds-card-service p { margin: 0; font-size: 14px; color: #7A7A7A; }
